// One item per enabled source, each carrying the criteria rows and the seen-set.
// The workflow deliberately holds no configuration of its own: criteria and
// sources are rows in Supabase so that "I'd also take Frederiksberg under 7k" is
// an insert, not an edit to a Code node.
const cfg = $input.first().json;
if (!cfg || cfg.ok !== true) {
  throw new Error('housing-ingest config failed: ' + JSON.stringify(cfg).slice(0, 300));
}
const criteria = cfg.criteria || [];
const sources = cfg.sources || [];
if (criteria.length === 0) {
  throw new Error('no enabled housing_criteria — add one before this can gate anything');
}

// An empty source list is not an error, but it IS the difference between "nothing
// new" and "nothing was even looked at", and a run that ends silently makes those
// two look identical. Same reason freshness comes from n8n_requests rather than
// from a row count.
if (sources.length === 0) {
  console.log('housing harvest: zero enabled sources — nothing was polled this run');
  return [];
}

return sources.map((s) => ({
  json: {
    source: s,
    criteria,
    seen: cfg.seen || [],
    // Additive to the pinned contract and worth carrying: boligzonen's ids are
    // slugs parsed out of a URL, so a URL-keyed guard is the one that cannot be
    // wrong about them.
    seen_urls: cfg.seen_urls || [],
  },
}));

