// --- node body ---
// One search page, then a capped number of detail fetches. lejebolig's listing
// ids are sequential, so in the steady state the high-water mark makes a poll
// cost exactly one request; the cap only binds on a first run or after an outage.
//
// robots.txt allows /lejeboliger/* and /lejebolig/*; it disallows /Hunter/*,
// /Handler/* and /kort/, none of which are touched. Content-Signal says
// ai-train=no — nothing here puts listing text into a training corpus.
const ctxs = $('Fan Out Sources').all().map((i) => i.json)
  .filter((c) => c.source && c.source.kind === SOURCE_KIND.lejebolig);
const items = $input.all();

const out = [];
for (let i = 0; i < items.length; i++) {
  // Pair each response with ITS OWN source row. The job harvester read
  // `$input.first()` here and silently discarded two of three feeds — a run that
  // looked healthy produced nothing from two whole sources.
  const ctx = ctxs[i] || ctxs[0];
  if (!ctx) continue;
  const html = items[i].json.data ?? items[i].json.body ?? '';

  const prefix = SOURCE_KIND.lejebolig + ' ';
  const seenIds = new Set(
    (ctx.seen || []).filter((s) => String(s).startsWith(prefix)).map((s) => String(s).slice(prefix.length)),
  );
  // The floor is max(numeric id already ingested). Nothing writes it back; see
  // nextIdRange's header for why it is a floor and not a cursor.
  let floor = null;
  for (const id of seenIds) {
    const n = Number(id);
    if (Number.isFinite(n) && (floor === null || n > floor)) floor = n;
  }

  const cap = Number(ctx.source.config && ctx.source.config.max_detail_fetches) || MAX_DETAIL_FETCHES;
  const found = parseLejeboligSearch(html);
  const picked = nextIdRange(floor, found, { cap, seen: seenIds });

  console.log(
    'lejebolig: ' + found.length + ' on page, ' + picked.fresh + ' fresh, ' +
      picked.stale + ' stale, ' + picked.take.length + ' fetching, ' +
      picked.deferred + ' deferred (floor=' + floor + ', high_water=' + picked.high_water + ')',
  );
  // Deferred listings are NOT queued for a later run — the floor moves past them.
  // On a race lane that is the right trade, but it must be visible.
  if (picked.deferred > 0) {
    console.log('lejebolig: ' + picked.deferred + ' listing(s) dropped by the cap; raise max_detail_fetches or poll faster');
  }

  for (const row of picked.take) {
    out.push({ json: { url: row.url, external_id: row.external_id, source_id: ctx.source.id } });
  }
}
return out;

