// --- node body ---
// The detail page carries a real schema.org RealEstateListing — the only one of
// five private portals that does. A page without one is SKIPPED rather than
// half-built: a row with a title and no rent passes the budget gate on a
// technicality and lands in the notify queue unpriceable.
const metas = $('Pick Lejebolig Listings').all().map((i) => i.json);
const items = $input.all();
const out = [];
let skipped = 0;

for (let i = 0; i < items.length; i++) {
  const meta = metas[i] || {};
  const html = items[i].json.data ?? items[i].json.body ?? '';
  const row = parseLejeboligJsonLd(html, { url: meta.url });
  if (!row) { skipped++; continue; }
  out.push({ json: { ...row, source_id: meta.source_id ?? null } });
}
if (skipped) console.log('lejebolig: ' + skipped + ' page(s) carried no RealEstateListing');
return out;

__EXTRACT_JS__

// --- node body ---
// robots.txt disallows only /en/rentals/* and a named SEO-bot list; the sitemap
// is published for crawling. Diff it against the seen-set and a lastmod window,
// and fetch only what is both new and recent — a normal poll is one 133 kB
// request and nothing else.
const ctx = $('Fan Out Sources').all().map((i) => i.json)
  .find((c) => c.source && c.source.kind === SOURCE_KIND.boligzonen);
if (!ctx) return [];


// Read every binary property on an item as text, whatever n8n's binary-data mode
// is. This is the half of the sitemap problem that a pure file cannot own.
//
// ⚠️ `item.binary[key].data` is base64 ONLY in the default in-memory mode. Under
// filesystem/S3 mode — which is what a 2 MB decompressed sitemap gets — the bytes
// live outside the item and `.data` is empty, with an `id` pointing at them
// instead. The first live run failed exactly there: the property existed
// (`file_0`) and decoded to nothing, which the old inline guard reported as
// "did not decompress to XML".
//
// `getBinaryDataBuffer` is the mode-independent read and is proxied correctly
// even when Code nodes run in an external task runner. The base64 path stays as a
// fallback so this still works on an instance where the helper is unavailable.
async function binaryCandidates(item) {
  const out = [];
  const binary = (item && item.binary) || {};
  for (const key of Object.keys(binary)) {
    let text = '';
    try {
      const buf = await this.helpers.getBinaryDataBuffer(0, key);
      if (buf && buf.length) text = buf.toString('utf8');
    } catch (e) {
      // fall through to the base64 path
    }
    if (!text) {
      const b64 = binary[key] && binary[key].data;
      if (b64) {
        try { text = Buffer.from(b64, 'base64').toString('utf8'); } catch (e) { text = ''; }
      }
    }
    out.push({ key, text });
  }
  return out;
}

const item = $input.first();
const found = sitemapXmlFromCandidates(await binaryCandidates.call(this, item));

// ⚠️ A dead sitemap must NOT be fatal. The first live run threw here, and because
// a Code-node throw fails the WHOLE execution the lejebolig branch's already-
// fetched listings never reached the batch POST: one broken lane zeroed a healthy
// one. That is the job-harvest lesson (one dead feed costs its own items and
// nothing else) arriving late.
//
// So this lane returns nothing and says so loudly. `Check Listing Rejects` runs
// the same tested check again AFTER the POST has landed and turns the run red
// there — the failure is still impossible to miss, it just no longer takes the
// other lane's rows with it. Returning [] SILENTLY would be the real sin: an
// empty lane is indistinguishable from a quiet one.
if (!found.ok) {
  const detail =
    'boligzonen: sitemap unreadable (' + found.reason + '). Binary keys: [' +
    found.keys.join(', ') + ']';
  console.error(detail + '. Continuing without this lane so the other lanes still post.');
  // A SENTINEL, not an empty array. `[]` is indistinguishable from 'nothing new
  // in the window', which is the normal steady state — and a lane that silently
  // harvests nothing forever is the exact failure this pipeline keeps writing
  // guards against. `Drop Lane Errors` removes it before it can reach an HTTP
  // node, and `Check Listing Rejects` reads it off THIS node's output (which
  // survives the filter) to fail the run after the batch has landed.
  return [{ json: { lane_error: detail } }];
}
const xml = found.xml;
console.log('boligzonen: sitemap read from binary property ' + found.key + ' (' + xml.length + ' chars)');

const cfg = ctx.source.config || {};
const windowMinutes = Number(cfg.window_minutes) || 180;
const cap = Number(cfg.max_detail_fetches) || MAX_DETAIL_FETCHES;

const prefix = SOURCE_KIND.boligzonen + ' ';
const seen = new Set(
  (ctx.seen || []).filter((s) => String(s).startsWith(prefix)).map((s) => String(s).slice(prefix.length)),
);

// Two guards on the same trousers. The slug guard above is the contract's
// `seen`; this one is `seen_urls`, which housing-ingest adds precisely because a
// sitemap diff has a URL long before it has parsed an id out of a slug. If
// boligzonen ever re-slugs a title the slug guard misses it and this one does not.
const seenUrls = new Set(ctx.seen_urls || []);

const all = parseBoligzonenSitemap(xml).filter((e) => !seenUrls.has(e.url));
const now = new Date();

// ⚠️ This sitemap is rebuilt roughly DAILY, not continuously — measured 30 hours
// stale on 2026-09-06. The window is therefore anchored on the file's own newest
// `lastmod`, not on the clock; a clock window narrower than the rebuild period
// matches nothing on every run, forever, and reports success. Log the age so an
// empty lane is explainable without re-probing the site.
const ageMin = boligzonenSitemapAgeMinutes(all, now);
const recent = boligzonenWindow(all, { now, windowMinutes });
const picked = nextIdRange(null, recent, { cap, seen });

console.log(
  'boligzonen: ' + all.length + ' unseen listing urls, sitemap age ' +
    (ageMin === null ? 'unknown' : ageMin + ' min') + ', ' + recent.length +
    ' within ' + windowMinutes + ' min of its newest entry, ' + picked.take.length +
    ' fetching, ' + picked.stale + ' already seen, ' + picked.deferred + ' deferred',
);
if (picked.deferred > 0) {
  console.log('boligzonen: ' + picked.deferred + ' listing(s) dropped by the cap; raise max_detail_fetches or narrow window_minutes');
}
return picked.take.map((e) => ({
  json: { url: e.url, external_id: e.external_id, lastmod: e.lastmod, source_id: ctx.source.id },
}));

// The lane-error sentinel from `Pick Boligzonen Listings` carries no `url`, and
// handing an HTTP node an undefined URL is a hard failure of the very run the
// sentinel exists to keep alive. It is dropped here; `Check Listing Rejects`
// still sees it, because `$('Node').all()` reads that node's OUTPUT and is
// unaffected by anything downstream.
return $input.all().filter((i) => i.json && i.json.url);

__EXTRACT_JS__

// --- node body ---
// No JSON-LD anywhere on this source: rent, rooms, size, address and the ad body
// are all server-rendered HTML. `lastmod` from the sitemap becomes posted_at —
// the page itself only says "Oprettet / Opdateret: I går", which is a phrase.
const metas = $('Pick Boligzonen Listings').all().map((i) => i.json);
const items = $input.all();
const out = [];
let thin = 0;

for (let i = 0; i < items.length; i++) {
  const meta = metas[i] || {};
  const html = items[i].json.data ?? items[i].json.body ?? '';
  const row = extractBoligzonenListing(html, { url: meta.url, lastmod: meta.lastmod });
  // No rent AND no title means the fetch failed or the layout moved. Skipping is
  // right; a row with neither is not a listing, it is an error wearing one.
  if (row.rent === null && !row.title) { thin++; continue; }
  out.push({ json: { ...row, source_id: meta.source_id ?? null } });
}
if (thin) console.log('boligzonen: ' + thin + ' page(s) yielded neither a rent nor a title');
return out;

