// --- node body ---
// Rule-only screening before anything expensive happens. A listing that fails
// every criteria row is not posted at all; one that passes any is posted once.
//
// ⚠️ The gate's VERDICTS ARE NOT PERSISTED. The pinned housing-ingest contract's
// listing shape has no room for them, so they are logged here and nowhere else.
// HOUSING_PLAN.md §3 describes a housing_matches table with gate_verdict and
// gate_reason columns; when that lands, this node grows a `matches` array and the
// server grows somewhere to put it. Until then a drop is auditable only in the
// n8n execution log — say so rather than letting someone assume the database
// knows why a listing never appeared.
const ctx = $('Fan Out Sources').first().json;
const criteria = ctx.criteria || [];
const out = [];
const dropped = [];

for (const item of $input.all()) {
  const listing = item.json;
  const verdicts = criteria.map((c) => ({ id: c.id, ...cheapGateHousing(listing, c) }));
  const passed = verdicts.filter((v) => v.verdict === 'pass');

  if (passed.length === 0) {
    dropped.push((listing.title || listing.url) + ' — ' + verdicts.map((v) => v.reason).join('; '));
    continue;
  }
  const flags = [...new Set(passed.flatMap((v) => v.flags))];
  console.log(
    'pass: ' + (listing.title || listing.url) + ' [' + passed.map((v) => v.id).join(',') + ']' +
      (flags.length ? ' flags=' + flags.join(',') : ''),
  );
  // Exactly the contract's fields go on the wire. Everything the extractors carry
  // for the gate's benefit — housing_type, available_from, shared, furnished —
  // is stripped here.
  out.push({ json: toIngestListing(listing) });
}

if (dropped.length) console.log('gate dropped ' + dropped.length + ':\n  ' + dropped.join('\n  '));
return out;

// One request for the whole run. An empty batch ends the run quietly rather
// than posting `listings: []` — the server would accept it and the response
// would be indistinguishable from a real, empty harvest.
const listings = $input.all().map((i) => i.json);
if (listings.length === 0) return [];
return [{ json: { user_id: $env.NEXUS_USER_ID, listings } }];

// Two jobs, in this order: report what the server did with the batch, then fail
// the run if a source lane died on the way here.
//
// The ORDER is the point. `Pick Boligzonen Listings` deliberately does not throw
// any more, so a sitemap failure no longer costs the lejebolig lane its rows —
// but a lane that quietly harvests nothing forever is exactly the silent failure
// this pipeline keeps guarding against. So the rows land first, and then this
// goes red.
const res = $input.first().json || {};
if (res.ok !== true) throw new Error('housing-ingest rejected the batch: ' + JSON.stringify(res).slice(0, 400));
const rejected = res.rejected || [];
if (rejected.length) {
  throw new Error(
    'housing-ingest rejected ' + rejected.length + ' listing(s): ' + JSON.stringify(rejected).slice(0, 600),
  );
}
console.log('stored ' + (res.listings ?? 0) + ' listing(s)');

// ⚠️ Read the SENTINEL, never the binary. The first version of this check called
// `this.helpers.getBinaryDataBuffer(0, key)` on `$('Decompress Sitemap')`'s item
// — and that helper is indexed against the CURRENT node's input, not the named
// node's, so it read this node's HTTP response instead. It then reported a
// perfectly healthy boligzonen lane as dead and failed a run that had just
// stored rows from it. A false alarm on a guard is worse than no guard: it
// teaches you to ignore the one that matters.
//
// Wrapped because a run with no boligzonen source never executes that node at
// all, and "the branch did not run" is not a failure.
let laneError = null;
try {
  for (const item of $('Pick Boligzonen Listings').all()) {
    if (item.json && item.json.lane_error) laneError = item.json.lane_error;
  }
} catch (e) {
  // node did not run in this execution
}

if (laneError) throw new Error('listings posted, but a lane was dead this run — ' + laneError);

return [{ json: res }];

// Lane A is a DAILY job riding a 30-minute trigger, because patch-deploy.mjs
// requires exactly one schedule trigger per workflow (it mirrors that trigger's
// wiring onto the CLI Trigger, and two would make "which one" a coin toss).
//
// So the cadence is a clock guard instead: the tick that lands in [hour:00, hour:30)
// runs, the one at :30 does not. HOUSING_PLAN.md's cadence table asks for daily at
// 07:00, and a building catalogue does not change hourly.
//
// The honest failure mode, stated so nobody debugs it as a bug: if the Mac is
// asleep across the whole window, Lane A is skipped that day. That is the
// "n8n for what is nice to happen" rule — a missed catalogue diff costs nothing,
// which is exactly why this is not on pg_cron.
const ctx = $input.first().json;
const hour = Number(ctx.source.config && ctx.source.config.daily_hour);
const target = Number.isFinite(hour) ? hour : 7;
const now = new Date();
const run = now.getHours() === target && now.getMinutes() < 30;
if (!run) return [];
return [{ json: ctx }];

// Page 1 told us the total. Emit the remaining page URLs plus the one
// short-wait-time call, all through a single HTTP node — two nodes' worth of work
// for one node's worth of traffic, and the tag on each item is how the builder
// tells them apart afterwards.
//
// mit.s.dk has NO robots.txt at all (404) and namespaces these endpoints
// /public/, so nothing is forbidden and nothing is granted. Daily, identified,
// and capped is what "indistinguishable from a person browsing" looks like.
const ctx = $('Daily Window?').first().json;
const cfg = ctx.source.config || {};
const base = cfg.api_base || 'https://mit.s.dk/api/v2/public';
const params = Object.assign({ min_zipcode: 2100, max_zipcode: 2200, min_rooms: 1 }, cfg.params || {});

const res = $input.first().json || {};
const count = Number(res.count);
const perPage = (res.results || []).length || 10;
const MAX_PAGES = Number(cfg.max_pages) || 10;

const out = [];
if (Number.isFinite(count) && perPage > 0) {
  const pages = Math.min(Math.ceil(count / perPage), MAX_PAGES);
  const qs = (page) =>
    Object.entries({ ...params, page }).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
  for (let p = 2; p <= pages; p++) out.push({ json: { kind: 'page', url: base + '/buildings/search/?' + qs(p) } });
  if (pages < Math.ceil(count / perPage)) {
    console.log('sdk: catalogue has ' + count + ' buildings but max_pages caps this run at ' + pages * perPage);
  }
} else {
  console.log('sdk: page 1 carried no usable count — importing page 1 only');
}

// The only Lane-A field that moves. One call.
out.push({ json: { kind: 'short_wait', url: base + '/buildings/short-wait-time/' } });
return out;

__EXTRACT_JS__

// --- node body ---
// A building is not a listing: it has no posted_at, it never goes away, and its
// interesting field is a QUEUE. It goes to buildings_sync, not to the listing
// batch, and it is never merged into the race lane.
const page1 = $('Fetch Buildings Page 1').first().json || {};
const plan = $('Plan Building Calls').all().map((i) => i.json);
const items = $input.all();

let shortWaitPks = null;   // null = call not made or failed = UNKNOWN
let shortWaitOk = false;

// Tag-to-response pairing is POSITIONAL, so if the two lists ever disagree in
// length the tags are meaningless — and a mis-tagged short-wait response read as
// a page would import ten Roskilde dorms as if they were the query result, while
// a mis-tagged page read as the short-wait list would flip short_wait on for the
// wrong buildings. Neither is recoverable from the row. So a length mismatch
// abandons the tagging entirely: every response is treated as a page and
// short_wait stays UNKNOWN. Wrong-and-loud beats wrong-and-plausible.
const aligned = plan.length === items.length;
if (!aligned) {
  console.log('sdk: ' + plan.length + ' planned call(s) but ' + items.length + ' response(s) — short_wait left unknown');
}
const pages = [page1];

for (let i = 0; i < items.length; i++) {
  const tag = plan[i] || {};
  const body = items[i].json;
  if (!body || body.error) continue;
  if (aligned && tag.kind === 'short_wait') {
    const rows = parseSdkBuildings(body);
    shortWaitPks = rows.map((r) => r.external_id);
    shortWaitOk = true;
    continue;
  }
  pages.push(body);
}

// ⚠️ Absence from a SUCCESSFUL short-wait call is real evidence of false.
// Absence because the call failed is evidence of nothing, and writing false for
// all 38 buildings would silently retract every short-wait flag in the database.
if (!shortWaitOk) console.log('sdk: short-wait-time was not read this run — short_wait stays unknown (null)');

const byId = new Map();
for (const page of pages) {
  for (const b of parseSdkBuildings(page, { shortWaitPks })) byId.set(b.external_id, b);
}
const buildings = [...byId.values()];
if (buildings.length === 0) return [];

console.log('sdk: ' + buildings.length + ' building(s), short_wait ' + (shortWaitOk ? 'known' : 'unknown'));
return [{ json: { action: 'buildings_sync', user_id: $env.NEXUS_USER_ID, buildings } }];

const res = $input.first().json || {};
if (res.ok !== true) throw new Error('buildings_sync failed: ' + JSON.stringify(res).slice(0, 400));
console.log('synced ' + (res.buildings ?? 0) + ' building(s)');
return [{ json: res }];
